// 场景：sink 端是普通 MySQL，不支持 XA 事务
// 方案：at-least-once + 业务唯一键 upsert + 对账

// 1. Sink: 用 INSERT ON DUPLICATE KEY 做幂等写
public class MySQLIdempotentSink extends RichSinkFunction<OrderEvent> {
    private transient Connection conn;
    private transient PreparedStatement upsert;

    @Override
    public void open(Configuration parameters) throws Exception {
        conn = DriverManager.getConnection(jdbcUrl, user, pass);
        conn.setAutoCommit(false);
        // order_id 是业务唯一键，version 用于处理乱序到达的更新
        upsert = conn.prepareStatement(
            "INSERT INTO orders (order_id, status, amount, version) " +
            "VALUES (?, ?, ?, ?) " +
            "ON DUPLICATE KEY UPDATE " +
            "status = IF(VALUES(version) > version, VALUES(status), status), " +
            "amount = IF(VALUES(version) > version, VALUES(amount), amount), " +
            "version = IF(VALUES(version) > version, VALUES(version), version)");
    }

    @Override
    public void invoke(OrderEvent event, Context ctx) throws Exception {
        upsert.setString(1, event.getOrderId());
        upsert.setString(2, event.getStatus());
        upsert.setBigDecimal(3, event.getAmount());
        upsert.setLong(4, event.getVersion());
        upsert.executeUpdate();
        conn.commit();
    }

    @Override
    public void close() throws Exception {
        if (conn != null) conn.close();
    }
}

